using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Core;
using UI.Input;

namespace Controllers
{
  public class LobbyVCamera : MonoBehaviour
  {
    [Header("Virtual Camera Target")]
    public Transform lookAt;

    [Header("Orbit Settings")]
    public float distance = 5f;
    public float rotationSpeed = 180f;
    public bool requireMouseButton = true;

    float currentAngle;
    bool isDragging;
    bool blockRotation;
    Vector3 lastMousePosition;

    void Start()
    {
      if (lookAt == null)
      {
        Debug.LogWarning("LobbyVCamera: lookAt Transform is not assigned.");
        return;
      }

      Vector3 fromTarget = transform.position - lookAt.position;
      distance = fromTarget.magnitude;

      currentAngle = Mathf.Atan2(fromTarget.x, fromTarget.z) * Mathf.Rad2Deg;
      UpdateCameraTransform();
    }

    void OnEnable()
    {
      if (EventChannelLocator.MainContainer != null)
        EventChannelLocator.MainContainer.changeCanRotateChannel.RegisterListener(OnChangeCanRotate);
    }

    void OnDisable()
    {
      if (EventChannelLocator.MainContainer != null)
        EventChannelLocator.MainContainer.changeCanRotateChannel.UnregisterListener(OnChangeCanRotate);
    }

    private void OnChangeCanRotate(bool canRotate)
    {
      blockRotation = canRotate;
    }

    void Update()
    {
      if (lookAt == null || blockRotation)
        return;

      bool dragging = !requireMouseButton || MobileInputHelper.GetPointerHeld();

      if (dragging)
      {
        if (!isDragging)
        {
          isDragging = true;
          lastMousePosition = MobileInputHelper.GetScreenPosition();
        }

        Vector3 currentPos = MobileInputHelper.GetScreenPosition();
        Vector3 delta = currentPos - lastMousePosition;
        lastMousePosition = MobileInputHelper.GetScreenPosition();

        currentAngle += delta.x * (rotationSpeed * UnityEngine.Time.deltaTime);
        UpdateCameraTransform();
      }
      else
      {
        isDragging = false;
      }
    }

    void UpdateCameraTransform()
    {
      if (lookAt == null)
        return;

      float rad = currentAngle * Mathf.Deg2Rad;
      distance = 3f;
      Vector3 offset = new Vector3(Mathf.Sin(rad), 0f, Mathf.Cos(rad)) * distance;
      Vector3 targetPosition = lookAt.position + offset;

      transform.position = new Vector3(targetPosition.x, transform.position.y, targetPosition.z);
      transform.LookAt(lookAt.position);
    }
  }
}

using System.Collections;
using System.Collections.Generic;
using Controllers.Character;
using Core;
using Controllers.Player;
using ExitGames.Client.Photon;
using ExitGames.Client.Photon.StructWrapping;
using Photon.Pun;
using UI.Framework.Panel;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using Hashtable = ExitGames.Client.Photon.Hashtable;
using Managers;
using UI;
using Controllers.Services;

namespace Controllers.Network
{
  public class Launcher : MonoBehaviourPunCallbacks, IObjectPoolService, IGameActionService
  {
    private bool isAutoCreate = false;
    private bool isJoiningRoom = false;
    private bool isQuittingToMenu = false;

    [SerializeField]
    public GameObject currentlySelectedCharacter;
    private Photon.Realtime.Player localPlayer;
    private InputField nameUI;
    private GameObject joinRoom;
    private GameObject TBGC;
    private GameObject joinRoomButton;
    private GameObject joinRoomInput;

    private bool isTest;

    // 拆分后的逻辑管理器
    private SpawnPointManager _spawnPointManager;
    private NetworkSceneFlow _sceneFlow;

    #region 单例模式
    public static Launcher instance;

    void Awake()
    {
      if (instance == null)
      {
        instance = this;
        DontDestroyOnLoad(gameObject);
        NetworkServiceLocator.RegisterObjectPoolService(this);
        NetworkServiceLocator.RegisterGameActionService(this);
      }
      else
      {
        Destroy(gameObject);
      }

      _sceneFlow = new NetworkSceneFlow(this);
      _spawnPointManager = new SpawnPointManager(this, currentlySelectedCharacter);

      // 只在大厅场景（场景索引1）初始化UI
      if (SceneManager.GetActiveScene().buildIndex == 1)
      {
        InitGetUI();
      }
    }
    #endregion

    void Start()
    {
      isTest = EventChannelLocator.MainContainer != null && EventChannelLocator.MainContainer.gameSettings != null && EventChannelLocator.MainContainer.gameSettings.IsTest;
      if (isTest)
        return;
      PhotonNetwork.AutomaticallySyncScene = true;
      UnityEngine.Application.runInBackground = true;
      PhotonNetwork.ConnectUsingSettings();
    }

    private void Update()
    {
      if (isTest)
        return;
      if (Input.GetKeyDown(KeyCode.Return))
      {
        ConfirmNickname();
      }
      if (Input.GetKeyDown(KeyCode.Escape))
      {
        CloseJoinRoomPanel();
      }
    }

    // ==================== 大厅 UI ====================

    public void ConfirmNickname()
    {
      if (string.IsNullOrEmpty(nameUI.text))
      {
        Debug.LogError("Name is empty");
        return;
      }
      else
      {
        PhotonNetwork.LocalPlayer.NickName = nameUI.text;
        Debug.Log($"修改昵称成功: {PhotonNetwork.LocalPlayer.NickName}");
      }
    }

    public void CloseJoinRoomPanel()
    {
      if (TBGC != null) TBGC.SetActive(false);
      if (joinRoomButton != null) joinRoomButton.SetActive(false);
      if (joinRoomInput != null) joinRoomInput.SetActive(false);
    }

    private void InitGetUI()
    {
      Debug.LogWarning("开始初始化UI组件---Launcher");
      nameUI = GameObject.Find("NameUI")?.GetComponent<InputField>();
      TBGC = GetInactiveObjectByName("TBGC");
      joinRoomButton = GetInactiveObjectByName("JoinRoomButton");
      joinRoomInput = GetInactiveObjectByName("JoinRoomInput");
      joinRoom = GameObject.Find("JoinRoom");

      // UI 初始化完成后注入 nameUI 到 SpawnPointManager
      _spawnPointManager.SetNameUI(nameUI);

      Initialize();
    }

    private void Initialize()
    {
      joinRoom
          .GetComponent<Button>()
          .onClick.AddListener(() =>
          {
            TBGC.SetActive(true);
            joinRoomButton.SetActive(true);
            joinRoomInput.SetActive(true);
          });

      joinRoomButton
          .GetComponent<Button>()
          .onClick.AddListener(() =>
          {
            string roomName = joinRoomInput.GetComponent<InputField>().text;
            if (string.IsNullOrEmpty(roomName))
            {
              Debug.LogError("Room name is empty");
              return;
            }
            {
              SwitchRoom(roomName);
            }
            CloseJoinRoomPanel();
          });

      if (TBGC != null)
      {
        Button closeBtn = TBGC.GetComponentInChildren<Button>(true);
        if (closeBtn != null && closeBtn.gameObject != joinRoomButton)
        {
          closeBtn.onClick.AddListener(CloseJoinRoomPanel);
        }
      }
    }

    public GameObject GetInactiveObjectByName(string objectName)
    {
      foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
      {
        if (root.name == objectName && !root.activeInHierarchy)
          return root;
        var found = FindChildRecursive(root.transform, objectName);
        if (found != null) return found.gameObject;
      }
      return null;
    }

    private static Transform FindChildRecursive(Transform parent, string name)
    {
      for (int i = 0; i < parent.childCount; i++)
      {
        var child = parent.GetChild(i);
        if (child.name == name) return child;
        var result = FindChildRecursive(child, name);
        if (result != null) return result;
      }
      return null;
    }

    // ==================== 连接 & 房间管理 ====================

    private string pendingRoomName = "";

    public void SwitchRoom(string newRoomName)
    {
      if (PhotonNetwork.InRoom)
      {
        pendingRoomName = newRoomName;
        isJoiningRoom = true;
        PhotonNetwork.LeaveRoom();
        Debug.Log("正在离开当前房间...");
      }
    }

    private void SetDefaultName()
    {
      if (string.IsNullOrEmpty(PhotonNetwork.LocalPlayer.NickName))
      {
        PhotonNetwork.LocalPlayer.NickName = "玩家" + PhotonNetwork.LocalPlayer.UserId;
      }
    }

    public override void OnConnectedToMaster()
    {
      if (isTest || SceneManager.GetActiveScene().buildIndex < 1)
        return;
      base.OnConnectedToMaster();
      PhotonNetwork.AutomaticallySyncScene = true;
      Debug.Log("Connected to master");
      string roomName = "Room_" + Random.Range(1000, 9999);
      SetDefaultName();
      if (!isAutoCreate)
      {
        PhotonNetwork.CreateRoom(
            roomName,
            new Photon.Realtime.RoomOptions() { MaxPlayers = 4, PublishUserId = true },
            default
        );
        isAutoCreate = true;
      }
    }

    public override void OnCreatedRoom()
    {
      if (isTest)
        return;
      base.OnCreatedRoom();
      Debug.Log("Created room: " + PhotonNetwork.CurrentRoom.Name);
    }

    public override void OnLeftRoom()
    {
      Debug.Log("已离开房间");
      if (isQuittingToMenu)
      {
        StartCoroutine(ShowAndLoadMainMenu());
        return;
      }
      // 切换房间：离开完成后安全地加入目标房间（OnLeftRoom 时已回到 Master 服务器）
      if (isJoiningRoom && !string.IsNullOrEmpty(pendingRoomName))
      {
        Debug.Log($"正在加入房间: {pendingRoomName}");
        PhotonNetwork.JoinRoom(pendingRoomName);
        isJoiningRoom = false;
      }
    }

    /// <summary>
    /// 退出房间并返回开始界面
    /// </summary>
    public void QuitToMainMenu()
    {
      if (PhotonNetwork.InRoom)
      {
        PhotonNetwork.AutomaticallySyncScene = false;
        _spawnPointManager.ClearLocalPlayerSpawnPoint();
        isQuittingToMenu = true;
        isAutoCreate = false;
        PhotonNetwork.LeaveRoom();
        Debug.Log("正在退出房间返回主菜单...");
      }
      else
      {
        StartCoroutine(ShowAndLoadMainMenu());
      }
    }

    private IEnumerator ShowAndLoadMainMenu()
    {
      yield return StartCoroutine(Loading.Instance.Show());
      LoadMainMenuScene();
    }

    private void LoadMainMenuScene()
    {
      isQuittingToMenu = false;
      pendingRoomName = "";
      isJoiningRoom = false;
      isAutoCreate = false;
      PhotonNetwork.AutomaticallySyncScene = false;
      SceneManager.LoadScene(0);
    }

    // ==================== PUN 回调路由 ====================

    public override void OnEnable()
    {
      base.OnEnable();
      SceneManager.sceneLoaded += OnSceneLoaded;
    }

    public override void OnDisable()
    {
      base.OnDisable();
      SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    public override void OnJoinedRoom()
    {
      Debug.Log("Joined room: " + PhotonNetwork.CurrentRoom.Name);
      if (isTest)
        return;
      base.OnJoinedRoom();
      _spawnPointManager.EnsurePlayerManagerExists();
      StartCoroutine(DelayJoinRoom());
    }

    IEnumerator DelayJoinRoom()
    {
      yield return new WaitForSeconds(0.5f);
      _spawnPointManager.CreatedOrJoinedRoom();
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
      if (scene.buildIndex == 1)
      {
        var roomJoinedChannel = EventChannelLocator.MainContainer.roomJoinedChannel;
        if (roomJoinedChannel != null)
          roomJoinedChannel.Raise(new RoomJoinedEventData());
      }

      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
        return;

      if (scene.buildIndex == 1)
      {
        EventChannelLocator.MainContainer.gameSettings.IsStayLobby = true;

        // 场景切换时重置暂停状态（防止卡牌面板打开时返回大厅导致 isPaused 卡在 true）
        if (Managers.GamePauseManager.isPaused)
        {
          EventChannelLocator.MainContainer.pauseChannel?.Raise(false);
        }

        InitGetUI();
        _sceneFlow.ResetForLobby();
        _sceneFlow.ResetLocalReady();

        if (PhotonNetwork.IsConnected && PhotonNetwork.InRoom)
        {
          StartCoroutine(_spawnPointManager.SpawnPlayerAfterDelay());
        }

        if (PhotonNetwork.IsConnected && !PhotonNetwork.InRoom && !isAutoCreate)
        {
          PhotonNetwork.AutomaticallySyncScene = true;
          string roomName = "Room_" + Random.Range(1000, 9999);
          SetDefaultName();
          PhotonNetwork.CreateRoom(
              roomName,
              new Photon.Realtime.RoomOptions() { MaxPlayers = 4, PublishUserId = true },
              default
          );
          isAutoCreate = true;
        }
        return;
      }

      if (scene.buildIndex > 1)
      {
        ServiceLocator.Get<GameManager>().isReady = false;
        EventChannelLocator.MainContainer.gameSettings.IsStayLobby = false;

        // 场景切换时重置暂停状态（防止卡牌面板打开时切场景导致 isPaused 卡在 true）
        if (Managers.GamePauseManager.isPaused)
        {
          EventChannelLocator.MainContainer.pauseChannel?.Raise(false);
        }

        // 进入游戏场景时重置流程标志（非 MasterClient 的 isRoomLoading/isLoadingScene 不会被 LoadLevel 隐式重置）
        _sceneFlow.ResetForLobby();

        Hashtable loadProps = new Hashtable
            {
                { PlayerPropertyKeys.Level, true },
                { PlayerPropertyKeys.Loaded, true },
                { PlayerPropertyKeys.PlayerName, PhotonNetwork.LocalPlayer.NickName },
            };

        PhotonNetwork.LocalPlayer.SetCustomProperties(loadProps);
        Debug.Log(
            $"[Launcher] 本地玩家场景加载完成，设置 PlayerLoaded=true: {PhotonNetwork.LocalPlayer.NickName}"
        );

        _spawnPointManager.CreatedOrJoinedRoom();
      }
    }

    public override void OnPlayerLeftRoom(Photon.Realtime.Player otherPlayer)
    {
      _spawnPointManager.HandlePlayerLeftRoom(otherPlayer);
    }

    public override void OnPlayerPropertiesUpdate(
        Photon.Realtime.Player targetPlayer,
        Hashtable changedProps
    )
    {
      if (changedProps.ContainsKey(PlayerPropertyKeys.Level))
      {
        Debug.Log(
            $"玩家 {targetPlayer.NickName} 的 PlayerLevel 属性已更新: {changedProps[PlayerPropertyKeys.Level]}"
        );
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.Ready))
      {
        _sceneFlow.CheckAllPlayersReady();
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.Loaded))
      {
        _sceneFlow.CheckAllPlayersLoaded();
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.SpawnPoint))
      {
        object spawnPointValue = changedProps[PlayerPropertyKeys.SpawnPoint];
        Debug.Log($"玩家 {targetPlayer.NickName} 的生成点更新: {spawnPointValue}");
      }
    }

    void OnDestroy()
    {
      _spawnPointManager.HandleDestroy();
    }

    // ==================== 接口门面（IGameActionService / IObjectPoolService） ====================

    // IGameActionService
    public void SetLocalReady(bool ready) => _sceneFlow.SetLocalReady(ready);

    // IObjectPoolService
    public void ReturnToLobby() => _sceneFlow.ReturnToLobby();

    // CharactorPanel 直接调用
    public void SwitchCharacter(string newCharacterName) => _spawnPointManager.SwitchCharacter(newCharacterName);
  }
}

using UnityEngine;

namespace UI.Input
{
    /// <summary>
    /// 输入处理器（纯 C# 实例类）
    /// 职责：仅读取 Unity 输入系统的原始数据，不做任何业务逻辑判断
    /// 由所在模块（如 PlayerController）驱动 Update()
    /// </summary>
    public class PlayerInputHandler
    {
        // ==================== 移动轴 ====================
        public float Horizontal { get; private set; }
        public float Vertical { get; private set; }

        // ==================== 鼠标位置 ====================
        public Vector3 MousePosition { get; private set; }

        // ==================== 键盘按键（帧事件） ====================
        public bool IsEscapePressed { get; private set; }
        public bool IsReturnPressed { get; private set; }
        public bool IsTabPressed { get; private set; }
        public bool IsTabReleased { get; private set; }

        // ==================== 鼠标按键（帧事件） ====================
        public bool IsMouseButtonDown { get; private set; }
        public bool IsMouseButtonUp { get; private set; }
        public bool IsMouseHeld { get; private set; }

        // ==================== 虚拟摇杆引用 ====================
        /// <summary>
        /// 设置当前激活的虚拟摇杆（由场景中的 VirtualJoystick 在 Awake/Start 时注册）
        /// </summary>
        public static VirtualJoystick ActiveJoystick { get; set; }

        /// <summary>
        /// 每帧更新所有输入状态，由持有者（如 PlayerController）调用
        /// </summary>
        public void Update()
        {
            // 移动轴：优先使用虚拟摇杆，回退到键盘
            if (ActiveJoystick != null && ActiveJoystick.IsActive)
            {
                Horizontal = ActiveJoystick.Direction.x;
                Vertical = ActiveJoystick.Direction.y;
            }
            else
            {
                Horizontal = UnityEngine.Input.GetAxis("Horizontal");
                Vertical = UnityEngine.Input.GetAxis("Vertical");
            }

            // 使用统一输入工具类，自动兼容触摸/鼠标
            MousePosition = MobileInputHelper.GetScreenPosition();

            IsEscapePressed = UnityEngine.Input.GetKeyDown(KeyCode.Escape);
            IsReturnPressed = UnityEngine.Input.GetKeyDown(KeyCode.Return);
            IsTabPressed = UnityEngine.Input.GetKeyDown(KeyCode.Tab);
            IsTabReleased = UnityEngine.Input.GetKeyUp(KeyCode.Tab);

            // 使用统一输入工具类，自动兼容触摸/鼠标
            IsMouseButtonDown = MobileInputHelper.GetPointerDown();
            IsMouseButtonUp = MobileInputHelper.GetPointerUp();
            IsMouseHeld = MobileInputHelper.GetPointerHeld();
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;

namespace UI.Input
{
    /// <summary>
    /// 虚拟摇杆控制器
    /// 挂载到摇杆 Panel 上，自动处理拖拽输入
    /// 输出标准化方向值（-1 ~ 1），供 PlayerInputHandler 读取
    /// </summary>
    public class VirtualJoystick : MonoBehaviour, IPointerDownHandler, IDragHandler, IPointerUpHandler
    {
        [Header("摇杆组件")]
        [SerializeField] private RectTransform background;
        [SerializeField] private RectTransform knob;

        [Header("摇杆参数")]
        [SerializeField] private float deadZone = 0.1f;

        /// <summary>
        /// 当前摇杆输出方向（标准化值 -1 ~ 1）
        /// </summary>
        public Vector2 Direction { get; private set; }

        /// <summary>
        /// 摇杆是否正在被使用
        /// </summary>
        public bool IsActive { get; private set; }

        private float _maxRadius;

        private void Awake()
        {
            if (background == null)
                background = GetComponent<RectTransform>();

            if (knob == null)
            {
                // 尝试从子对象中查找名为 "Knob" 的 RectTransform
                Transform knobTransform = transform.Find("Knob");
                if (knobTransform != null)
                    knob = knobTransform.GetComponent<RectTransform>();
                else
                    knob = transform.GetChild(0)?.GetComponent<RectTransform>();
            }

            // 计算摇杆最大半径（使用 rect 获取实际渲染尺寸，不受 anchor 影响）
            _maxRadius = background.rect.width / 2f;
            Direction = Vector2.zero;

            // 自动注册为当前激活摇杆
            PlayerInputHandler.ActiveJoystick = this;

            Debug.Log($"[VirtualJoystick] 初始化完成，最大半径: {_maxRadius}，背景尺寸: {background.rect.size}");

            if (FindObjectOfType<UnityEngine.EventSystems.EventSystem>() == null)
                Debug.LogWarning("[VirtualJoystick] 场景中未找到 EventSystem，UI 事件将无法工作！");
        }

        private void OnDestroy()
        {
            // 销毁时取消注册
            if (PlayerInputHandler.ActiveJoystick == this)
            {
                PlayerInputHandler.ActiveJoystick = null;
            }
        }

        public void OnPointerDown(PointerEventData eventData)
        {
            IsActive = true;
            OnDrag(eventData);
        }

        public void OnDrag(PointerEventData eventData)
        {
            Vector2 localPoint;
            if (RectTransformUtility.ScreenPointToLocalPointInRectangle(
                    background,
                    eventData.position,
                    eventData.pressEventCamera,
                    out localPoint))
            {
                // localPoint 在背景 RectTransform 的本地空间：
                // 中心 (0,0)，向右 +X，向上 +Y，所以 localPoint 本身就是偏移量
                float magnitude = localPoint.magnitude;

                // 限制半径
                Vector2 offset = localPoint;
                if (magnitude > _maxRadius)
                {
                    offset = localPoint.normalized * _maxRadius;
                    magnitude = _maxRadius;
                }

                // 移动摇杆圆点
                knob.anchoredPosition = offset;

                // 计算标准化方向（-1 ~ 1）
                float normalizedMagnitude = magnitude / _maxRadius;
                Direction = offset.normalized * Mathf.Clamp01(normalizedMagnitude);

                // 应用死区
                if (Direction.magnitude < deadZone)
                {
                    Direction = Vector2.zero;
                }
            }
        }

        public void OnPointerUp(PointerEventData eventData)
        {
            IsActive = false;
            Direction = Vector2.zero;
            knob.anchoredPosition = Vector2.zero;
        }

        /// <summary>
        /// 重置摇杆状态
        /// </summary>
        public void ResetJoystick()
        {
            IsActive = false;
            Direction = Vector2.zero;
            knob.anchoredPosition = Vector2.zero;
        }

        private void OnDisable()
        {
            ResetJoystick();
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using NetworkTarget = Controllers.Network.NetworkTarget;
using Controllers.CardData;
