namespace Controllers.Character
{
  public class WizardBoy : PlayerController
  {
    [SerializeField]
    private Button testCardEffect;

    [Header("对象池预制体")]
    [SerializeField] private GameObject impactCannonLightenPrefab;
    [SerializeField] private GameObject impactCannonHitLightenPrefab;
    [SerializeField] private GameObject impactCannonWinterPrefab;
    [SerializeField] private GameObject impactCannonHitWinterPrefab;
    [SerializeField] private GameObject impactCannonGrassPrefab;
    [SerializeField] private GameObject impactCannonHitGrassPrefab;

    protected override void Start()
    {
      base.Start();

      // ★ 仅本地玩家设置 MagicUpgradeManager 的角色卡牌类型
      // 防止非本地角色的 Start() 覆盖当前客户端的卡牌池
      if (NetworkServiceLocator.PlayerService.IsOwnerOf(gameObject))
      {
        // 通知 MagicUpgradeManager 当前角色为 WizardBoy，专属卡牌使用对应卡池
        MagicUpgradeManager.instance?.SetCurrentEventName(CharacterCardType.WizardBoy);

        if (testCardEffect != null)
        {
          testCardEffect.onClick.AddListener(() =>
          {
            SwitchElement(Element.Grass);
          });
        }
      }
    }

    protected override void OnEnable()
    {
      base.OnEnable();
    }

    protected override void OnDisable()
    {
      base.OnDisable();
    }

    protected override void OnSkillQuery(SkillQueryData data)
    {
      if (data.queryType == SkillQueryType.GetMaxAttackCount)
      {
        data.intValue = GetMaxAttackCount();
      }
    }

    protected override void SwitchElement(Element element)
    {
      switch (element)
      {
        case Element.Lightning:
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonLightenPool, impactCannonLightenPrefab, 10));
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitLightenPool, impactCannonHitLightenPrefab, 20));
          break;
        case Element.Winter:
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonWinterPool, impactCannonWinterPrefab, 10));
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitWinterPool, impactCannonHitWinterPrefab, 20));
          break;
        case Element.Grass:
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonGrassPool, impactCannonGrassPrefab, 10));
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitGrassPool, impactCannonHitGrassPrefab, 20));
          break;
      }

      if (!EventChannelLocator.MainContainer.gameSettings.IsTest)
      {
        NetworkServiceLocator.DomainRpcService?.InvokeRPC(
            "RPC_InitElementPool",
            NetworkTarget.Others,
            NetworkServiceLocator.ObjectService.GetViewID(gameObject),
            (int)element
        );
      }

      base.SwitchElement(element);
    }

    protected override void OnApplicationCard(CardConfigBase card)
    {
      base.OnApplicationCard(card);
      switch (card.Name)
      {
        case "流光穿透":
          attributePlayer.AddMaxAttackCount(1);
          break;
        case "流光连射":
          attributePlayer.AddComboCount(1);
          break;
        case "惊鸿照影":
          attributePlayer.SetCurrentElement(Element.Lightning);
          SwitchElement(Element.Lightning);
          attributePlayer.AddAttackPower(20);
          break;
        case "森芒初露":
          attributePlayer.SetCurrentElement(Element.Grass);
          SwitchElement(Element.Grass);
          movementData.healthRecover += 2;
          attributePlayer.SetHealthRecover(movementData.healthRecover);
          break;
        case "流光分裂":
          attributePlayer.SetSplit(true);
          attributePlayer.AddSplitCount(1);
          break;
        case "碎雪回风":
          attributePlayer.SetCurrentElement(Element.Winter);
          SwitchElement(Element.Winter);
          attributePlayer.AddAttackPower(20);
          break;
      }
    }

    /// <summary>
    /// 由 DomainRpcBridge.RPC_InitElementPool 调用 — 在其他客户端初始化元素对象池
    /// </summary>
    public void HandleInitElementPool(int elementInt)
    {
      Element element = (Element)elementInt;

      switch (element)
      {
        case Element.Lightning:
          int countLighten = 0;
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateGetPoolCount(ObjectPoolConst.ImpactCannonLightenPool, (c) => countLighten = c));
          if (countLighten == 0)
          {
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonLightenPool, impactCannonLightenPrefab, 10));
          }
          int countHitLighten = 0;
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateGetPoolCount(ObjectPoolConst.ImpactCannonHitLightenPool, (c) => countHitLighten = c));
          if (countHitLighten == 0)
          {
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitLightenPool, impactCannonHitLightenPrefab, 20));
          }
          break;
        case Element.Winter:
          int countWinter = 0;
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateGetPoolCount(ObjectPoolConst.ImpactCannonWinterPool, (c) => countWinter = c));
          if (countWinter == 0)
          {
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonWinterPool, impactCannonWinterPrefab, 10));
          }
          int countHitWinter = 0;
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateGetPoolCount(ObjectPoolConst.ImpactCannonHitWinterPool, (c) => countHitWinter = c));
          if (countHitWinter == 0)
          {
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitWinterPool, impactCannonHitWinterPrefab, 20));
          }
          break;
        case Element.Grass:
          int countGrass = 0;
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateGetPoolCount(ObjectPoolConst.ImpactCannonGrassPool, (c) => countGrass = c));
          if (countGrass == 0)
          {
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonGrassPool, impactCannonGrassPrefab, 10));
          }
          int countHitGrass = 0;
          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateGetPoolCount(ObjectPoolConst.ImpactCannonHitGrassPool, (c) => countHitGrass = c));
          if (countHitGrass == 0)
          {
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitGrassPool, impactCannonHitGrassPrefab, 20));
          }
          break;
      }
    }
  }
}

using System.Collections;
using UnityEngine;
using ExitGames.Client.Photon;
using Photon.Pun;
using Controllers.Services;
using UI.Framework.Panel;
using Hashtable = ExitGames.Client.Photon.Hashtable;

namespace Controllers.Network
{
    /// <summary>
    /// 准备系统、场景加载协调、返回大厅逻辑（从 Launcher 拆分）
    /// 非 MonoBehaviour 纯逻辑类，由 Launcher 持有和驱动协程
    /// </summary>
    public class NetworkSceneFlow
    {
        private readonly MonoBehaviour _coroutineRunner;

        private bool isRoomLoading = false;
        private bool isLoadingScene = false;
        private bool allPlayersLoaded = false;

        public NetworkSceneFlow(MonoBehaviour coroutineRunner)
        {
            _coroutineRunner = coroutineRunner;
        }

        // ==================== 准备系统 ====================

        /// <summary>设置本地玩家的准备状态</summary>
        public void SetLocalReady(bool ready)
        {
            if (!PhotonNetwork.InRoom)
            {
                Debug.LogWarning("[NetworkSceneFlow] 无法设置准备状态：未在房间中");
                return;
            }

            Hashtable props = new Hashtable { { PlayerPropertyKeys.Ready, ready } };
            PhotonNetwork.LocalPlayer.SetCustomProperties(props);
            Debug.Log($"[NetworkSceneFlow] 本地玩家准备状态: {ready} - {PhotonNetwork.LocalPlayer.NickName}");

            // 显式通知本地玩家的属性变更，确保本地 WorldSpaceUI 头顶文字能收到更新
            // （PUN2 的 OnPlayerPropertiesUpdate 不保证对本地客户端回调本地玩家的属性变更）
            var playerService = NetworkServiceLocator.PlayerService as PhotonPlayerService;
            if (playerService != null)
            {
                playerService.NotifyPropertyChanged(
                    PhotonNetwork.LocalPlayer.ActorNumber,
                    PlayerPropertyKeys.Ready,
                    ready
                );
            }

            CheckAllPlayersReady();
        }

        private bool AllPlayersReady()
        {
            foreach (Photon.Realtime.Player player in PhotonNetwork.PlayerList)
            {
                if (
                    !player.CustomProperties.ContainsKey(PlayerPropertyKeys.Ready)
                    || (bool)player.CustomProperties[PlayerPropertyKeys.Ready] == false
                )
                {
                    return false;
                }
            }
            return true;
        }

        public void CheckAllPlayersReady()
        {
            if (isRoomLoading || isLoadingScene)
            {
                return;
            }

            if (AllPlayersReady())
            {
                Debug.Log("[NetworkSceneFlow] 所有玩家已准备，开始加载场景");
                isRoomLoading = true;
                _coroutineRunner.StartCoroutine(LoadLevelAfterDelay());
            }
        }

        // ==================== 场景加载 ====================

        public IEnumerator LoadLevelAfterDelay(int index = 2)
        {
            isLoadingScene = true;
            yield return new WaitForSeconds(2f);

            yield return Loading.Instance.Show();

            if (PhotonNetwork.IsMasterClient)
            {
                PhotonNetwork.LoadLevel(index);
            }
        }

        /// <summary>检查所有玩家是否已加载场景（由 Launcher.OnPlayerPropertiesUpdate 委托）</summary>
        public void CheckAllPlayersLoaded()
        {
            if (isLoadingScene || allPlayersLoaded)
            {
                return;
            }

            foreach (Photon.Realtime.Player player in PhotonNetwork.PlayerList)
            {
                if (
                    !player.CustomProperties.ContainsKey(PlayerPropertyKeys.Loaded)
                    || (bool)player.CustomProperties[PlayerPropertyKeys.Loaded] == false
                )
                {
                    Debug.Log($"[NetworkSceneFlow] 等待玩家 {player.NickName} 加载场景...");
                    return;
                }
            }

            allPlayersLoaded = true;
            Debug.Log("[NetworkSceneFlow] 所有玩家已加载完成，开始游戏！");
        }

        // ==================== 返回大厅 ====================

        /// <summary>返回大厅（保持房间连接）</summary>
        public void ReturnToLobby()
        {
            if (!PhotonNetwork.InRoom)
            {
                Debug.LogWarning("[NetworkSceneFlow] 不在房间中，无法返回大厅");
                return;
            }

            _coroutineRunner.StartCoroutine(ReturnToLobbyCoroutine());
        }

        private IEnumerator ReturnToLobbyCoroutine()
        {
            yield return Loading.Instance.Show();

            if (PhotonNetwork.IsMasterClient)
            {
                PhotonNetwork.LoadLevel(1);
                Debug.Log("[NetworkSceneFlow] 房主发起切换到大厅场景");
            }
            else
            {
                Debug.Log("[NetworkSceneFlow] 等待房主同步场景...");
            }
        }

        // ==================== 状态重置（场景切换时由 Launcher 调用） ====================

        /// <summary>重置所有流程标志（大厅和游戏场景切换时均由 Launcher 调用）</summary>
        public void ResetForLobby()
        {
            isRoomLoading = false;
            isLoadingScene = false;
            allPlayersLoaded = false;
        }

        /// <summary>重置本地玩家的准备状态</summary>
        public void ResetLocalReady()
        {
            if (
                PhotonNetwork.IsConnected
                && PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.Ready)
            )
            {
                Hashtable props = new Hashtable { { PlayerPropertyKeys.Ready, false } };
                PhotonNetwork.LocalPlayer.SetCustomProperties(props);
                Debug.Log("[NetworkSceneFlow] 重置本地玩家就绪状态为 false");
            }
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using ExitGames.Client.Photon;
using Photon.Pun;
using Managers;
using Core;
using Controllers.Services;
using Controllers.Player;
using UI;
using Hashtable = ExitGames.Client.Photon.Hashtable;

namespace Controllers.Network
{
    /// <summary>
    /// 玩家生成、生成点管理、角色切换逻辑（从 Launcher 拆分）
    /// 非 MonoBehaviour 纯逻辑类，由 Launcher 持有和驱动
    /// </summary>
    public class SpawnPointManager
    {
        private readonly Launcher _launcher;
        private readonly GameObject _currentlySelectedCharacter;

        private InputField _nameUI;
        private Photon.Realtime.Player _localPlayer;
        private GameObject _localPlayerObject;

        public GameObject LocalPlayerObject => _localPlayerObject;
        public Photon.Realtime.Player LocalPlayer => _localPlayer;

        public SpawnPointManager(Launcher launcher, GameObject currentlySelectedCharacter)
        {
            _launcher = launcher;
            _currentlySelectedCharacter = currentlySelectedCharacter;
        }

        /// <summary>大厅 UI 初始化完成后延迟注入 nameUI</summary>
        public void SetNameUI(InputField nameUI) => _nameUI = nameUI;

        // ==================== 玩家生成入口 ====================

        /// <summary>玩家加入房间 / 场景加载完成后的统一生成入口</summary>
        public void CreatedOrJoinedRoom()
        {
            if (SceneManager.GetActiveScene().buildIndex < 1)
            {
                Debug.Log("[SpawnPointManager] 当前不是游戏场景，跳过玩家生成");
                return;
            }
            ServiceLocator.Get<GameManager>().FindSpawnPoints();
            Debug.Log("[SpawnPointManager] 执行 CreatedOrJoinedRoom");

            EnsurePlayerManagerExists();

            GameObject player = SpawnPlayer();

            if (player != null)
            {
                InitializePlayerSettings(player);
                SetupPlayerUI(player);
            }

            SetupRoomInfo();
        }

        /// <summary>大厅场景延迟生成角色</summary>
        public IEnumerator SpawnPlayerAfterDelay()
        {
            yield return new WaitForEndOfFrame();

            yield return new WaitUntil(() =>
                ServiceLocator.Get<GameManager>() != null && ServiceLocator.Get<GameManager>().GetEmptySpawnPoint() != null
            );

            ApplySavedCharacter();

            GameObject player = SpawnPlayer();
            if (player != null)
            {
                InitializePlayerSettings(player);
                SetupPlayerUI(player);
                Debug.Log("[SpawnPointManager] 在大厅重新生成角色");
            }
        }

        // ==================== 核心：生成玩家 ====================

        public GameObject SpawnPlayer()
        {
            int localActorNumber = NetworkServiceLocator.PlayerService.GetLocalActorNumber();
            var gameManager = ServiceLocator.Get<GameManager>();

            // 根据 ActorNumber 确定性地分配生成点（不同玩家必然得到不同生成点）
            ISpawnPoint sp = gameManager.GetSpawnPointForPlayer(localActorNumber);
            Transform spawnPoint = (sp as MonoBehaviour)?.transform;

            // 仅当确定性分配的生成点被"其他"玩家占用时才回退（RPC 同步滞后期间 IsEmpty 可能误报）
            if (sp != null && !sp.IsEmpty() && sp.GetOccupiedByPlayer() != localActorNumber)
            {
                sp = gameManager.GetEmptySpawnPoint()?.GetComponent<ISpawnPoint>();
                spawnPoint = (sp as MonoBehaviour)?.transform;
            }

            if (spawnPoint == null)
            {
                Debug.LogError("[SpawnPointManager] 没有可用的生成点！");
                return null;
            }

            if (sp != null)
            {
                sp.SetOccupied(true, localActorNumber);
            }

            Vector3 spawnPosition = CalculateSpawnPosition(spawnPoint);

            GameObject player = PhotonNetwork.Instantiate(
                _currentlySelectedCharacter.name,
                spawnPosition,
                spawnPoint.rotation
            );

            player.transform.rotation = Quaternion.Euler(0, spawnPoint.rotation.eulerAngles.y, 0);
            player.name = "Player_" + PhotonNetwork.LocalPlayer.UserId;

            if (sp != null)
            {
                var props = new Hashtable { { PlayerPropertyKeys.SpawnPoint, sp.Id } };
                PhotonNetwork.LocalPlayer.SetCustomProperties(props);
            }

            return player;
        }

        // ==================== 重新生成 / 角色切换 ====================

        public void RespawnCharacter()
        {
            int currentSpawnPointId = -1;
            if (PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
            {
                currentSpawnPointId = (int)PhotonNetwork.LocalPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
            }

            if (_localPlayerObject != null)
            {
                PhotonNetwork.Destroy(_localPlayerObject);
            }

            GameObject newPlayer = RespawnAtSpawnPoint(currentSpawnPointId);

            if (newPlayer != null)
            {
                InitializePlayerSettings(newPlayer);
                SetupPlayerUI(newPlayer);
                Debug.Log($"[SpawnPointManager] 在原生成点 {currentSpawnPointId} 重新生成角色");
            }
        }

        private GameObject RespawnAtSpawnPoint(int spawnPointId)
        {
            ISpawnPoint targetSpawnPoint = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);

            if (targetSpawnPoint == null)
            {
                Debug.LogWarning($"[SpawnPointManager] 找不到ID为 {spawnPointId} 的生成点，使用第一个空闲生成点");
                return SpawnPlayer();
            }

            int localActorNumber = NetworkServiceLocator.PlayerService.GetLocalActorNumber();
            targetSpawnPoint.SetOccupied(true, localActorNumber);

            Transform spawnTransform = ((MonoBehaviour)targetSpawnPoint).transform;
            Vector3 spawnPosition = CalculateSpawnPosition(spawnTransform);

            GameObject player = PhotonNetwork.Instantiate(
                _currentlySelectedCharacter.name,
                spawnPosition,
                spawnTransform.rotation
            );

            player.transform.rotation = Quaternion.Euler(0, spawnTransform.rotation.eulerAngles.y, 0);
            player.name = "Player_" + PhotonNetwork.LocalPlayer.UserId;

            return player;
        }

        public void SwitchCharacter(string newCharacterName)
        {
            _currentlySelectedCharacter.name = newCharacterName;
            RespawnCharacter();
        }

        // ==================== 生成点清理 ====================

        /// <summary>清理本地玩家的生成点占用（退出房间前调用）</summary>
        public void ClearLocalPlayerSpawnPoint()
        {
            if (!PhotonNetwork.IsConnected || !PhotonNetwork.InRoom)
                return;

            if (PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
            {
                int spawnPointId = (int)PhotonNetwork.LocalPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
                ISpawnPoint sp = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);
                if (sp != null && (sp as MonoBehaviour) != null && sp.GetOccupiedByPlayer() == PhotonNetwork.LocalPlayer.ActorNumber)
                {
                    sp.ForceRelease();
                    Debug.Log("[SpawnPointManager] 退出前释放生成点");
                }
            }
        }

        /// <summary>其他玩家离开房间时释放其生成点（由 Launcher.OnPlayerLeftRoom 委托）</summary>
        public void HandlePlayerLeftRoom(Photon.Realtime.Player otherPlayer)
        {
            Debug.Log($"[SpawnPointManager] 玩家 {otherPlayer.NickName} 离开房间");
            if (!PhotonNetwork.IsConnected || !PhotonNetwork.InRoom)
            {
                Debug.LogWarning("[SpawnPointManager] 连接状态异常，跳过生成点释放");
                return;
            }
            if (otherPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
            {
                int spawnPointId = (int)otherPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
                ISpawnPoint sp = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);
                if (sp != null)
                {
                    sp.ForceRelease();
                    Debug.Log($"[SpawnPointManager] 释放玩家 {otherPlayer.NickName} 占用的生成点 {spawnPointId}");
                }
            }
        }

        /// <summary>Launcher OnDestroy 时清理本地生成点</summary>
        public void HandleDestroy()
        {
            if (PhotonNetwork.IsConnected && PhotonNetwork.InRoom)
            {
                if (PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
                {
                    int spawnPointId = (int)PhotonNetwork.LocalPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
                    ISpawnPoint sp = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);
                    if (sp != null && (sp as MonoBehaviour) != null)
                    {
                        sp.ForceRelease();
                    }
                }
            }
        }

        // ==================== 玩家初始化 ====================

        private void InitializePlayerSettings(GameObject player)
        {
            if (!EventChannelLocator.MainContainer.gameSettings.IsStayLobby)
            {
                GameObject vcam = player.transform.Find("VirtualCamera")?.gameObject;
                if (vcam != null)
                {
                    vcam.SetActive(true);
                }
            }
            else
            {
                player.transform.LookAt(
                    new Vector3(0.182999998f, player.transform.position.y, -0.219999999f)
                );
            }
        }

        private void SetupPlayerUI(GameObject player)
        {
            _localPlayer = PhotonNetwork.LocalPlayer;
            if (string.IsNullOrEmpty(_localPlayer.NickName))
                _localPlayer.NickName = "玩家" + _localPlayer.UserId;

            if (_nameUI != null)
            {
                _nameUI.text = _localPlayer.NickName;
            }

            var worldSpaceUI = player.GetComponentInChildren<WordlSpaceUI>();
            if (worldSpaceUI != null)
            {
                worldSpaceUI.UpDatePlayerName(_localPlayer.NickName);
            }

            _localPlayerObject = player;
        }

        // ==================== 辅助方法 ====================

        public void EnsurePlayerManagerExists()
        {
            if (PlayerManager.instance == null)
            {
                PlayerManager existingPM = Object.FindObjectOfType<PlayerManager>();
                if (existingPM == null)
                {
                    GameObject pmObj = new GameObject("PlayerManager");
                    pmObj.AddComponent<PlayerManager>();
                    Debug.Log("[SpawnPointManager] 创建 PlayerManager");
                }
            }
            else
            {
                EventChannelLocator.MainContainer.gameActionChannel.Raise(Core.Channels.General.GameActionType.SyncAllPlayers);
            }
        }

        private Vector3 CalculateSpawnPosition(Transform spawnPoint)
        {
            if (EventChannelLocator.MainContainer.gameSettings.IsStayLobby)
            {
                return spawnPoint.position;
            }

            Vector2 randomCircle = Random.insideUnitCircle * 10.0f;
            Vector3 randomOffset = new Vector3(randomCircle.x, spawnPoint.position.y, randomCircle.y);
            return spawnPoint.position + spawnPoint.TransformVector(randomOffset);
        }

        private void ApplySavedCharacter()
        {
            int savedIndex = SaveManager.SelectedCharacterIndex;
            switch (savedIndex)
            {
                case CharactorIndex.BingNv:
                    _currentlySelectedCharacter.name = CharactorName.BingNv;
                    break;
                case CharactorIndex.WiZardBoy:
                default:
                    _currentlySelectedCharacter.name = CharactorName.WiZardBoy;
                    break;
            }
        }

        private void SetupRoomInfo()
        {
            GameObject roomNameObj = GameObject.Find("RoomName");
            if (roomNameObj != null && PhotonNetwork.CurrentRoom != null)
            {
                Text roomNameText = roomNameObj.GetComponent<Text>();
                if (roomNameText != null)
                {
                    roomNameText.text = PhotonNetwork.CurrentRoom.Name;
                }
            }
        }
    }
}

using System.Collections.Generic;
using Controllers.Services;
using Photon.Pun;
using Photon.Realtime;
using UnityEngine;

namespace Controllers.Network
{
    public class PhotonPlayerService : INetworkPlayerService
    {
        private readonly Dictionary<int, Photon.Realtime.Player> _playerCache = new();

        public event System.Action<int, string, object> OnPlayerPropertyChanged;
        public event System.Action<int, string> OnPlayerEnteredRoom;
        public event System.Action<int, string> OnPlayerLeftRoom;
        public event System.Action OnLocalJoinedRoom;

        public bool IsConnectedAndInRoom => PhotonNetwork.IsConnectedAndReady && PhotonNetwork.InRoom;
        public bool IsMasterClient => PhotonNetwork.IsMasterClient;

        public int GetLocalActorNumber()
        {
            if (PhotonNetwork.LocalPlayer != null)
                return PhotonNetwork.LocalPlayer.ActorNumber;
            return -1;
        }

        public string GetLocalUserId()
        {
            if (PhotonNetwork.LocalPlayer != null)
                return PhotonNetwork.LocalPlayer.UserId;
            return string.Empty;
        }

        public bool IsOwnerOf(GameObject gameObject)
        {
            if (gameObject == null) return false;
            PhotonView pv = gameObject.GetComponentInParent<PhotonView>();
            return pv != null && pv.IsMine;
        }

        public void SetCustomProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom) return;
            var props = new ExitGames.Client.Photon.Hashtable { { key, value } };
            PhotonNetwork.LocalPlayer.SetCustomProperties(props);
        }

        public object GetCustomProperty(string key)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.LocalPlayer == null)
                return null;
            return PhotonNetwork.LocalPlayer.CustomProperties[key];
        }

        public int[] GetAllActorNumbers()
        {
            if (!IsConnectedAndInRoom) return System.Array.Empty<int>();
            var players = PhotonNetwork.PlayerList;
            int[] actorNumbers = new int[players.Length];
            for (int i = 0; i < players.Length; i++)
            {
                actorNumbers[i] = players[i].ActorNumber;
            }
            return actorNumbers;
        }

        public object GetPlayerCustomProperty(int actorNumber, string key)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.CustomProperties[key] : null;
        }

        public string GetPlayerUserId(int actorNumber)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.UserId : null;
        }

        public string GetPlayerNickName(int actorNumber)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.NickName : null;
        }

        public bool AllPlayersHaveProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom) return false;
            foreach (var player in PhotonNetwork.PlayerList)
            {
                if (!player.CustomProperties.ContainsKey(key))
                    return false;
                if (!player.CustomProperties[key].Equals(value))
                    return false;
            }
            return true;
        }

        public void SetRoomCustomProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.CurrentRoom == null) return;
            var props = new ExitGames.Client.Photon.Hashtable { { key, value } };
            PhotonNetwork.CurrentRoom.SetCustomProperties(props);
        }

        public object GetRoomCustomProperty(string key)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.CurrentRoom == null)
                return null;
            return PhotonNetwork.CurrentRoom.CustomProperties[key];
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发 PUN 属性变更事件
        /// </summary>
        public void NotifyPropertyChanged(int actorNumber, string key, object value)
        {
            OnPlayerPropertyChanged?.Invoke(actorNumber, key, value);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发玩家加入事件
        /// </summary>
        public void NotifyPlayerEnteredRoom(int actorNumber, string userId)
        {
            var player = FindPlayer(actorNumber);
            if (player != null)
                _playerCache[actorNumber] = player;
            OnPlayerEnteredRoom?.Invoke(actorNumber, userId);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发玩家离开事件
        /// </summary>
        public void NotifyPlayerLeftRoom(int actorNumber, string userId)
        {
            _playerCache.Remove(actorNumber);
            OnPlayerLeftRoom?.Invoke(actorNumber, userId);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发本地玩家加入完成事件
        /// </summary>
        public void NotifyLocalJoinedRoom()
        {
            _playerCache.Clear();
            foreach (var player in PhotonNetwork.PlayerList)
                _playerCache[player.ActorNumber] = player;
            OnLocalJoinedRoom?.Invoke();
        }

        private Photon.Realtime.Player FindPlayer(int actorNumber)
        {
            if (_playerCache.TryGetValue(actorNumber, out var cached))
                return cached;
            foreach (var player in PhotonNetwork.PlayerList)
            {
                if (player.ActorNumber == actorNumber)
                {
                    _playerCache[actorNumber] = player;
                    return player;
                }
            }
            return null;
        }
    }
}

using Controllers.Services;
using Photon.Pun;
using UnityEngine;

namespace Controllers.Network
{
    public class PhotonObjectService : INetworkObjectService
    {
        public GameObject Instantiate(string prefabName, Vector3 position, Quaternion rotation)
        {
            return PhotonNetwork.Instantiate(prefabName, position, rotation);
        }

        public GameObject InstantiateRoomObject(string prefabName, Vector3 position, Quaternion rotation)
        {
            return PhotonNetwork.InstantiateRoomObject(prefabName, position, rotation);
        }

        public void InvokeRPC(MonoBehaviour source, string methodName, NetworkTarget target, params object[] parameters)
        {
            PhotonView photonView = source.GetComponent<PhotonView>();
            if (photonView == null)
            {
                Debug.LogWarning($"[PhotonObjectService] {source.name} 上没有 PhotonView 组件，无法调用 RPC {methodName}");
                return;
            }
            photonView.RPC(methodName, NetworkTargetMapper.ToRpcTarget(target), parameters);
        }

        public int GetViewID(Component component)
        {
            PhotonView photonView = component.GetComponent<PhotonView>();
            return photonView != null ? photonView.ViewID : -1;
        }

        public int GetViewID(GameObject gameObject)
        {
            if (gameObject == null) return -1;
            PhotonView photonView = gameObject.GetComponent<PhotonView>();
            return photonView != null ? photonView.ViewID : -1;
        }

        public GameObject FindByViewID(int viewId)
        {
            PhotonView photonView = PhotonView.Find(viewId);
            return photonView != null ? photonView.gameObject : null;
        }

        public string GetOwnerNickname(MonoBehaviour source)
        {
            if (source == null) return "";
            PhotonView pv = source.GetComponentInParent<PhotonView>();
            return pv != null && pv.Owner != null ? pv.Owner.NickName : "";
        }

        public int GetOwnerActorNumber(Component source)
        {
            if (source == null) return -1;
            PhotonView pv = source.GetComponentInParent<PhotonView>();
            return pv != null && pv.Owner != null ? pv.Owner.ActorNumber : -1;
        }
    }
